package app.lianxu.independent
import org.junit.Assert.*
import org.junit.Test

class ProviderCatalogTest {
 private fun config(p:String,m:String,base:String=ProviderPresets.get(p).base)=ModelConfig("c","synthetic",p,base,m)
 @Test fun uniquePresetsAndLegacyAddressesRemainUnchanged(){
  assertEquals(20,ProviderPresets.all.size);assertEquals(20,ProviderPresets.all.map{it.id}.toSet().size)
  mapOf("moonshot" to "https://api.moonshot.ai/v1","silicon-cn" to "https://api.siliconflow.cn/v1","deepseek" to "https://api.deepseek.com","minimax-cn" to "https://api.minimax.cn/v1","minimax-intl" to "https://api.minimax.io/v1").forEach{(id,url)->assertEquals(url,ProviderPresets.get(id).base)}
  assertEquals("custom",ProviderPresets.get("unrecognized-old-id").id)
 }
 @Test fun newUrlsAndAuthAreExplicit(){
  mapOf("gemini" to "https://generativelanguage.googleapis.com/v1beta/openai","tokenhub-cn" to "https://tokenhub.tencentmaas.com/v1","tokenhub-intl" to "https://tokenhub-intl.tencentmaas.com/v1","qianfan" to "https://qianfan.baidubce.com/v2","stepfun-cn" to "https://api.stepfun.com/v1","stepfun-intl" to "https://api.stepfun.ai/v1","moonshot-cn" to "https://api.moonshot.cn/v1","opencode-go" to "https://opencode.ai/inference/go/openai/v1").forEach{(id,url)->val p=ProviderPresets.get(id);assertEquals(url,p.base);assertEquals("Authorization",p.authHeader);assertNull(ConfigRules.urlError(p.base))}
  assertNull(ProviderPresets.get("opencode-go").modelsPath);assertEquals("https://opencode.ai/inference/go/v1/models",ProviderPresets.get("opencode-go").modelsUrl);assertTrue(ProviderPresets.get("opencode-go").openAiChatModelsOnly);assertNull(ConfigRules.urlError(ProviderPresets.get("opencode-go").modelsUrl!!))
 }
 @Test fun regionsGroupWithoutDuplicatingBrands(){val groups=ProviderCatalog.groups(false,all=true);assertEquals(16,groups.size);for(n in listOf("腾讯 TokenHub","Moonshot / Kimi","阶跃星辰","MiniMax"))assertEquals(2,groups.single{it.name==n}.regions.size)}
 @Test fun commonListStaysSmallAndSearchFindsNewAliases(){assertEquals(5,ProviderCatalog.groups(false).size);mapOf("谷歌" to "gemini","腾讯 新加坡" to "tokenhub-intl","文心" to "qianfan","opencodego" to "opencode-go","月之暗面" to "moonshot-cn","stepfun" to "stepfun-cn").forEach{(q,id)->assertTrue(q,ProviderCatalog.groups(false,q).flatMap{it.regions}.any{it.id==id})}}
 @Test fun embeddingServicesRequireDocumentedTextSupport(){val ids=ProviderCatalog.groups(true,all=true).flatMap{it.regions}.map{it.id};assertTrue(ids.containsAll(listOf("silicon-cn","openai","bailian-cn","zhipu-cn","gemini","tokenhub-cn","tokenhub-intl","qianfan","custom")));assertFalse(ids.any{it in setOf("ark-cn","opencode-go","stepfun-cn","deepseek")})}
 @Test fun modelIdsAreNotGuessedByEmbeddingSubstring(){assertEquals(ProviderModelKind.UNKNOWN,ProviderCatalog.modelKind(config("gemini","imaginary-embedding-unknown")));assertEquals(ProviderModelKind.TEXT_EMBEDDING,ProviderCatalog.modelKind(config("gemini","gemini-embedding-001")));assertEquals(ProviderModelKind.TEXT_EMBEDDING,ProviderCatalog.modelKind(config("silicon-cn","Qwen/Qwen3-Embedding-4B")))}
 @Test fun multimodalProtocolsAreNotSentToTextEndpoint(){for(c in listOf(config("ark-cn","doubao-embedding-vision-251215"),config("tokenhub-cn","kinfra-vl-embedding-8b"),config("bailian-cn","qwen3-vl-embedding")))assertEquals(ProviderModelKind.OTHER_PROTOCOL,ProviderCatalog.modelKind(c))}
 @Test fun overriddenAndCustomUrlsStayUnknownButEditable(){assertEquals(ProviderModelKind.UNKNOWN,ProviderCatalog.modelKind(config("gemini","gemini-embedding-001","https://example.invalid/original/v1")));assertEquals(ProviderModelKind.UNKNOWN,ProviderCatalog.modelKind(config("custom","my-vector-model","https://example.invalid/v1")));assertNull(ConfigRules.validate("custom","https://example.invalid/v1","my-vector-model","synthetic-only"))}
 @Test fun purposeFilterRetainsSelectedLegacyAndExplicitUnknownRoute(){val legacy=config("custom","old-text").copy(id="legacy",baseUrl="https://example.invalid/v1");val known=config("gemini","gemini-embedding-001").copy(id="known");assertEquals(listOf(known),ProviderCatalog.configurations(listOf(legacy,known),ModelPurpose.EMBEDDING,""));assertEquals(listOf(legacy,known),ProviderCatalog.configurations(listOf(legacy,known),ModelPurpose.EMBEDDING,"legacy"));assertEquals(2,ProviderCatalog.configurations(listOf(legacy,known),ModelPurpose.EMBEDDING,"",true).size);assertEquals(listOf(legacy),ProviderCatalog.configurations(listOf(legacy,known),ModelPurpose.CHAT,""))}
 @Test fun goUsesTruthfulStableConversationMetadata(){val request=TextChatRequest(listOf(WireMessage("user","synthetic")),conversationId=ProviderRequestMetadata.conversation("role-a"));val first=ProviderRequestMetadata.headers(config("opencode-go","synthetic-model"),request);assertEquals("Lianxu (Android; companion-chat)",first["User-Agent"]);assertEquals(first,ProviderRequestMetadata.headers(config("opencode-go","synthetic-model"),request.copy(outputLimit=2049)));assertNotEquals(request.conversationId,ProviderRequestMetadata.conversation("role-b"));assertFalse(first["User-Agent"]!!.contains("coding-agent"));assertTrue(ProviderRequestMetadata.headers(config("custom","m","https://example.invalid/v1"),request).isEmpty())}
 @Test fun savedCurrentGoRouteIsRecognizedWithoutRewritingIt(){val c=config("custom","m","https://opencode.ai/inference/go/openai/v1/");assertTrue(ProviderRequestMetadata.headers(c,TextChatRequest(listOf(WireMessage("user","s")))).containsKey("x-opencode-session"));assertTrue(c.baseUrl.endsWith("/"))}
 @Test fun sessionHeaderCannotCarryInjectedText(){try{TextChatRequest(listOf(WireMessage("user","s")),conversationId="x\r\nInjected:yes");fail()}catch(_:IllegalArgumentException){}}
 @Test fun newEmbeddingLimitsBindToExactEndpointsAndNeverTruncate(){
  val t=config("tokenhub-cn","kinfra-text-embedding-4b");val limits=MemoryEmbeddingLimits.of(t);assertEquals(128,limits.items);assertEquals(2000,limits.inputChars);assertTrue(runCatching{limits.batches(t,listOf("a".repeat(2001)))}.isFailure);assertEquals(2048,MemoryEmbeddingLimits.of(t.copy(baseUrl="https://example.invalid/v1")).items)
  val g=config("gemini","gemini-embedding-001");assertEquals(2048,MemoryEmbeddingLimits.of(g).inputTokens);assertEquals(listOf(1,1),MemoryEmbeddingLimits.of(g).batches(g,listOf("a","b")).map{it.size})
  val b=config("qianfan","embedding-v1");assertEquals(384,MemoryEmbeddingLimits.of(b).inputTokens);assertEquals(16,MemoryEmbeddingLimits.of(b).items);assertTrue(runCatching{MemoryEmbeddingLimits.of(b).batches(b,listOf("a".repeat(1001)))}.isFailure)
 }
 @Test fun workspaceTextModelsUseOnlyTheDocumentedBailianHost(){assertEquals(ProviderModelKind.TEXT_EMBEDDING,ProviderCatalog.modelKind(config("bailian-cn","text-embedding-v4","https://workspace.cn-beijing.maas.aliyuncs.com/compatible-mode/v1")));assertEquals(ProviderModelKind.UNKNOWN,ProviderCatalog.modelKind(config("bailian-cn","text-embedding-v4","https://workspaceXcn-beijingXmaasXaliyuncsXcom/compatible-mode/v1")))}
 @Test fun customOfficialHostCannotBypassKnownMultimodalProtocol(){for((id,model) in mapOf("ark-cn" to "doubao-embedding-vision-251215","tokenhub-cn" to "kinfra-vl-embedding-8b","bailian-cn" to "qwen3-vl-embedding")){val c=config("custom",model,ProviderPresets.get(id).base);assertEquals(ProviderModelKind.OTHER_PROTOCOL,ProviderCatalog.modelKind(c))}}
 @Test fun goTargetAcceptsOnlyParsedHttpsDefaultOriginAndExactRawPath(){
  for(url in listOf("https://opencode.ai/inference/go/openai/v1","https://OPENCODE.AI/inference/go/openai/v1/","HTTPS://OpEnCoDe.Ai:443/inference/go/openai/v1///")){assertTrue(url,ProviderRequestMetadata.verifiedGoBase(url));assertNull(ConfigRules.urlError(url))}
 }
 @Test fun goTargetRejectsSimilarHostsPortsUserinfoAndAlternatePaths(){
  for(url in listOf("http://opencode.ai/inference/go/openai/v1","https://opencode.ai.evil/inference/go/openai/v1","https://evil-opencode.ai/inference/go/openai/v1","https://opencode.ai./inference/go/openai/v1","https://opencode.ai:8443/inference/go/openai/v1","https://u@opencode.ai/inference/go/openai/v1","https://opencode.ai@evil.invalid/inference/go/openai/v1","https://opencode.ai/inference/openai/v1","https://opencode.ai/zen/go/v1","https://opencode.ai/Inference/go/openai/v1","https://opencode.ai/inference/go/openai/v1/../v1","https://opencode.ai/%69nference/go/openai/v1","https://opencode.ai/inference/go/openai/v1?x=y","https://opencode.ai/inference/go/openai/v1#x"))assertFalse(url,ProviderRequestMetadata.verifiedGoBase(url))
 }
 @Test fun presetIdentityCannotForwardGoSessionToAnotherHost(){val c=config("opencode-go","m","https://example.invalid/v1");assertTrue(ProviderRequestMetadata.headers(c,TextChatRequest(listOf(WireMessage("user","s")))) .isEmpty());assertTrue(ProviderRequestMetadata.blockedGoPreset(c));assertEquals(ProviderRequestMetadata.GO_UNVERIFIED_NOTICE,ProviderRequestMetadata.compatibilityNotice(c));assertEquals("https://example.invalid/v1",c.baseUrl)}
 @Test fun unrelatedCustomHostHasNoGoHeaderOrGoBlock(){val c=config("custom","m","https://example.invalid/v1");assertTrue(ProviderRequestMetadata.headers(c,TextChatRequest(listOf(WireMessage("user","s")))).isEmpty());assertFalse(ProviderRequestMetadata.blockedGoPreset(c));assertNull(ProviderRequestMetadata.compatibilityNotice(c))}
 @Test fun legacyOpenCodeRouteIsKeptWithExplicitCompatibilityNotice(){val c=config("custom","m","https://opencode.ai/zen/go/v1");assertFalse(ProviderRequestMetadata.blockedGoPreset(c));assertNotNull(ProviderRequestMetadata.compatibilityNotice(c));assertTrue(ProviderRequestMetadata.headers(c,TextChatRequest(listOf(WireMessage("user","s")))).isEmpty());assertEquals("https://opencode.ai/zen/go/v1",c.baseUrl)}
}
